	mouseDY = ((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - my) / 1000.0;
}

function mouseReleased() {
	mouseDX = 0.0;
	mouseDY = 0.0;
	isMouseDragging = false;
}

function mouseWheel(event) {
	if (widget[0].alterValueDirectly(acceleratedAmount(event.delta * 0.0001)))
		isDirty = true;
}


function setAlterDirection(dir) {
	alterDirection = dir;
	fastMode = true;
	isDirty = true;
}

// ----------------------------------------------------
var keyPressPace = 0; 

function keyPressed() {
	keyPressPace = 10; 

	switch (keyCode) {
		case UP_ARROW:
			alterIndexDirection = -1;
			break;
		case DOWN_ARROW:
			alterIndexDirection = +1;
			break;
		case 33: // pageup
			alterIndexDirection = -3;
			break;
		case 34: // pagedn
			alterIndexDirection = +3;
			break;
		case LEFT_ARROW:
			setAlterDirection(-1);
			break;
		case RIGHT_ARROW:
			setAlterDirection(+1);
			break;
	}

	switch (key) {
		case 'a':
		case 'A': 
			shiftKeyDown = true;
			break;
		case 'z':
		case 'Z': 
			controlKeyDown = true;
			break;
		case ' ':
			cycleVisibility();
			break;
		case 'Q':
			debugWidgets();
			break;
	}
}

function keyReleased() {
	switch (key) {
		case 'a':
		case 'A':
			shiftKeyDown = false;
			break;
		case 'z':
		case 'Z':
			controlKeyDown = false;
			break;
	}

	switch (keyCode) {
		case UP_ARROW:
		case DOWN_ARROW:
		case 33: 
		case 34: 
			alterIndexDirection = 0;
			break;
		case LEFT_ARROW:
		case RIGHT_ARROW:
			alterDirection = 0;
			break;
	}
}


function acceleratedAmount(amount) {
	if (shiftKeyDown && controlKeyDown) amount *= 50;
	else
	if (shiftKeyDown) amount *= 0.1;
	else
	if (controlKeyDown) amount *= 10.0;
	return amount;
}


function draw() {
	if (mouseDX != 0 || mouseDY != 0) {
		if (widget[1].alterValueDirectly(acceleratedAmount(mouseDX * 0.01)))
			isDirty = true;
		if (widget[2].alterValueDirectly(acceleratedAmount(mouseDY * 0.01)))
			isDirty = true;
	}

	if (alterIndexDirection != 0) {
		keyPressPace += 1;
		if (keyPressPace < 5) return;
		keyPressPace = 0;

		alterIndex(alterIndexDirection);
		return;
	}

	if (!isDirty) return;
	isDirty = false;

	if (alterDirection != 0) {
		if (!widget[wIndex].alterValue(alterDirection)) // trying to alter past limits is ignored
			return;
		isDirty = true;

		if (widget[wIndex].kind == kindInteger) alterDirection = 0; // no auto repeat for integer widgets
	}

	background(0);
	shader(gpu);
	widgetsUploadToGPU();
	gpu.setUniform("zoomY", widget[0].value * windowAspectRatio);
	rect(0, 0, width, height);
	updateWidgets();
}

// === Tab: shader ===
const fragmentShader = `
precision highp float;
varying vec2 vTexCoord;

uniform vec2 center;
uniform float zoom,zoomY,loopDen,contrast,bright,iterationDelta,colorMult;
uniform int loopCount;

vec2 complexPower(vec2 value, float power) {
    float rr = value.x * value.x + value.y * value.y; // radius squared
    if(rr == 0.0) return vec2(0.0001,0.0001);

    float p1 = pow(rr, power / 2.0);
    float arg = atan(value.y, value.x);
    return vec2(cos(power * arg) * p1, sin(power * arg) * p1);
}

// ----------------------------------------------

float loopLnA(float v) {
	v = abs(v);

	for(int i=0;i<100;++i) { 
		if(i >= loopCount) break;

		v = 2.0 - log(v);
	}

	return v;
}

// ----------------------------------------------

vec3 generateColor(float x) {
	x = cos(x * colorMult);

	float r = (1.0-x)*(1.0-x);
  float g = x*x;
  float b = 2.0*(1.0-x)*x;

	return vec3(r,g,b);
}

// ----------------------------------------------

void main() {
	vec2 z = vec2(0.0,0.0);
	float wires = 0.0;
	float denominator = loopDen; //loopLnA(loopDen);
	float z2,iteration = 0.0;

	vec2 cc = vec2(center.x + (vTexCoord.x  - 0.5) * zoom,center.y + (vTexCoord.y - 0.5) * zoomY);

	for(int i=0;i<250;i++) {

		z = complexPower(z,2.0) + cc;

		z2 = dot(z,z);
		if (z2 > 4.0) break;

		wires += 6.0 - loopLnA(iteration - z2) / denominator;

		iteration = z2 * iterationDelta; //+= iterationDelta;
	}

	vec4 color = vec4(bright,bright,bright,1.0);  // brightness

	color.xyz += generateColor(abs(wires) * 0.01); // loopLnA

	color.x = 0.5 + (color.x - 0.5) * contrast;		// contrast
	color.y = 0.5 + (color.y - 0.5) * contrast;
	color.z = 0.5 + (color.z - 0.5) * contrast;

	gl_FragColor = color;
}
`;

