// === Tab: widget ===
const kindFloat = 0;
const kindInteger = 1;
const kindVec2 = 2;
const kindVec3 = 3;
const kindBool = 4;

var widget = []; // all widgets
var wIndex = 0; // current widget index
var wx = 10; // position for placement of next widget
var wy = 10;
var wyHop = 16; // vertical gap between widgets 
var wygroup = 5; // vertical gap between widget groups
var wsize = 125; // widget width

// --------------------------------------------------------
class Widget {
	constructor(p1, p2, p3, p4, p5, p6, p7, p8) {
		this.field = createInput("text");
		this.gpuName = p1;
		this.displayName = p2;
		this.value = p3;
		this.min = p4;
		this.max = p5;
		this.delta = p6;
		this.kind = p7;
		this.tintCode = p8;

		this.index = widget.length;

		this.posx = wx;
		this.posy = wy;
		wy += wyHop;
	}

	isFloatType() {
		return this.kind == kindFloat || this.kind == kindVec2 || this.kind == kindVec3;
	}

	// --------------------------------------------------------
	// update value in direction specified 

	alterValue(dir) {
		var amount = float(dir);
		var old = this.value;

		if (this.isFloatType())
			amount = acceleratedAmount(amount);

		if(this.kind == kindInteger) { // wrap around
			this.value += amount;
			if(this.value > this.max) this.value = this.min; else
			if(this.value < this.min) this.value = this.max;
		}
		else {
			this.value = min(max(this.value + this.delta * amount, this.min), this.max);
		}

		if (this.value != old) { // value was changed
			this.update();
			return true;
		}

		return false;
	}

	alterValueDirectly(amount) {
		let old = this.value;
		this.value = min(max(this.value + amount, this.min), this.max);

		if (this.value != old) { // value was changed
			this.update();
			return true;
		}

		return false;
	}

	// --------------------------------------------------------
	// update value display 

	update() {
		this.field.remove();

		let str = this.displayName + "  ";

		switch (this.kind) {
			case kindFloat:
			default:
				str += nf(this.value, 0, 4);
				break;
			case kindInteger:
				str += int(this.value);
				break;
			case kindBool:
				str += (int(this.value) > 0.1 ? "Yes " : "No ");
				break;
		}

		this.field = createInput(str);
		this.field.style('font-size', '10px');
		this.field.size(wsize);
		this.field.position(this.posx, this.posy);

		if (this.index == wIndex) {
			this.field.style('background-color', color(255, 0, 0));
			this.field.style('color', color(255));
		} else {
			this.field.style('background-color', tintColor[this.tintCode]);
			this.field.style('color', color(0));
		}

		this.setVisible(visibilityStyle == 1);
	}

	// --------------------------------------------------------
	// update GPU uniform copy of widget value

	upload() {
		switch (this.kind) {
			case kindVec2:
				var x = this.value;
				var y = widget[this.index + 1].value;
				gpu.setUniform(this.gpuName, [x, y]);
				break;
			case kindVec3:
				var x = this.value;
				var y = widget[this.index + 1].value;
				var z = widget[this.index + 2].value;
				gpu.setUniform(this.gpuName, [x, y, z]);
				break;
			case kindFloat:
				gpu.setUniform(this.gpuName, this.value);
				break;
			case kindInteger:
				gpu.setUniform(this.gpuName, int(this.value))
				break;
			case kindBool:
				gpu.setUniform(this.gpuName, int(this.value) < 0.9 ? false : true);
				break;
		}
	}

	// ----------------------------------------------------
	// update widget visibility 

	setVisible(onoff) {
		if (onoff)
			this.field.style('visibility', 'visible');
		else
			this.field.style('visibility', 'hidden');
	}
};

// ----------------------------------------------------
// add widget entry to storage

function addWidget(p1, p2, p3, p4, p5, p6, p7, p8) {
	widget.push(new Widget(p1, p2, p3, p4, p5, p6, p7, p8));
}

// ----------------------------------------------------
// mouse click received. move widget focus if hit

function clickedOnWidget(x, y) {
	for (var i = 0; i < widget.length; ++i) {
		if (x >= widget[i].posx && x < widget[i].posx + wsize &&
			y >= widget[i].posy && y < widget[i].posy + wyHop) {
			wIndex = widget[i].index;

			// if boolean widget then flip value as well
			if (widget[i].kind == kindBool)
				widget[i].value = widget[i].value > 0.1 ? 0.0 : 1.0;

			updateWidgets();
			return;
		}
	}
}

// ----------------------------------------------------
// update all widgets

function updateWidgets() {
	for (var i = 0; i < widget.length; ++i)
		widget[i].update();
	updateSummaryWidget();

	updateVisibilitySettings();
}

// ----------------------------------------------------
// move widget focus with wrap-around

function alterIndex(dir) { // assume +1,-1
	wIndex += dir;
	if (wIndex < 0) wIndex = widget.length - 1;
	else
	if (wIndex >= widget.length) wIndex = 0;

	updateWidgets();
}

// ----------------------------------------------------
// move focus to neighboring group (denoted by background tintCode)

function widgetIndexHop(dir) { // assume +1,-1
	let oldTint = widget[wIndex].tintCode;
	while (true) {
		wIndex += dir;
		if (wIndex < 0) wIndex += widget.length;
		if (wIndex >= widget.length) wIndex -= widget.length;
		if (widget[wIndex].tintCode != oldTint) break;
	}

	updateWidgets();
}

// ----------------------------------------------------
// copy all widget values into respective uniform value

function widgetsUploadToGPU() {
	for (var i = 0; i < widget.length; ++i) {
		widget[i].upload();
		if (widget[i].kind == kindVec2) i += 1;
		if (widget[i].kind == kindVec3) i += 2;
	}
}

// ----------------------------------------------------
// for floating point widgets: set current widget value to zero (or assigned minimum)

function zeroWidgetValue() {
	if (widget[wIndex].isFloatType())
		widget[wIndex].value = min(max(0, widget[wIndex].min), widget[wIndex].max);
}

// ----------------------------------------------------
// 0 = widgets all visible, summary hidden
// 1 = only summary is visible
// 2 = all hidden
var visibilityStyle = 0;

function cycleVisibility() {
	if (++visibilityStyle > 2) visibilityStyle = 0;
	updateVisibilitySettings();
}

// ----------------------------------------------------
// update visibility of all widgets + summary widget

function updateVisibilitySettings() {
	switch (visibilityStyle) {
		case 0:
			for (var i = 0; i < widget.length; ++i)
				widget[i].setVisible(true);
			summaryWidget.style('visibility', 'hidden');
			break;
		case 1:
			for (var i = 0; i < widget.length; ++i)
				widget[i].setVisible(false);
			summaryWidget.style('visibility', 'visible');
			break;
		case 2:
			summaryWidget.style('visibility', 'hidden');
			break;
	}
}

// ----------------------------------------------------
// update summary widget value to match focused widget

function updateSummaryWidget() {
	summaryWidget.remove();
	summaryWidget = createInput(widget[wIndex].field.value());
	summaryWidget.style('font-size', '16px');
	summaryWidget.size(200);
	summaryWidget.position(10, 10);
}

// ----------------------------------------------
// 'Q' was pressed.  build a 'ParamList' definition using the current settings, and display in console.
// build rendition of float value with trailing zeros removed

function debugWidgets() {
	console.log("-----------------------------------------");
	var str = "";
	for (var i = 0; i < widget.length; ++i)
		str += i + " " + widget[i].displayName + " : " + widget[i].value + "\n";
	console.log(str);
}

